<script setup lang="ts">import{onMounted,ref}from'vue';import{getGuides,type Guide}from'../services/content';const guides=ref<Guide[]>([]),loading=ref(true);onMounted(async()=>{try{guides.value=await getGuides()}finally{loading.value=false}})</script>
<template><section class="page-hero"><p class="eyebrow">CAPACITACIÓN</p><h1>Guías para <em>avanzar.</em></h1><p>Recursos claros para ayudarte a dar cada paso con confianza.</p></section><section class="content-section"><div v-if="loading" class="empty-state">Cargando guías…</div><div v-else-if="guides.length" class="guide-grid"><article v-for="(guide,index) in guides" :key="guide.id"><span>0{{index+1}}</span><h3>{{guide.title}}</h3><p>{{guide.summary||'Contenido educativo disponible próximamente.'}}</p><button class="text-link">Leer guía →</button></article></div><div v-else class="empty-state">No hay guías disponibles actualmente.</div></section></template>

